  { name: 'Pencarian', id: 'search', target: 'ops_console', col: 0, row: 2 },
  { name: 'Notifikasi', id: 'notification', target: 'notifications', col: 1, row: 2 },
  { name: 'Kendaraan', id: 'motor-vehicle', target: 'car_protection', col: 2, row: 2 },
