                </button>
                <div className="flex items-center gap-2 mb-3">
                  <div className="flex-1 h-px bg-ds-card2" />
                  <span className="text-[10px] text-ds-ink2 font-bold uppercase tracking-widest">atau URL</span>
                  <div className="flex-1 h-px bg-ds-card2" />
                </div>
                <input
