import React, { useState, useRef } from 'react';
import { ShieldCheck, FileText, Loader2, Download, AlertCircle, CheckCircle2 } from 'lucide-react';
import { Language } from '../../types';
import { acceptAgreement, SpAgentAgreement } from '../../services/supabaseService';
import { generateAgreementPDF } from '../../services/agreementPdf';
import { AGREEMENT_META, AGREEMENT_CLAUSES } from './agreementContent';

interface Props {
  agent: any;
  lang: Language;
  onAccepted: (a: SpAgentAgreement) => void;
}

// Full-screen blocking gate. An agent cannot use the app until they read the
// agreement and submit their legal name + 16-digit KTP as electronic consent.
const AgentAgreementGate: React.FC<Props> = ({ agent, lang, onAccepted }) => {
  const t = (en: string, id: string) => (lang === Language.EN ? en : id);
  const [fullName, setFullName] = useState<string>(agent?.name ?? '');
  const [ktp, setKtp] = useState<string>(agent?.ktp ?? '');
  const [checked, setChecked] = useState(false);
  const [scrolledEnd, setScrolledEnd] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState<SpAgentAgreement | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const ktpValid = /^[0-9]{16}$/.test(ktp);
  const nameValid = fullName.trim().length >= 3;
  const canSubmit = checked && scrolledEnd && ktpValid && nameValid && !submitting;

  const onScroll = () => {
    const el = scrollRef.current;
    if (!el) return;
    if (el.scrollTop + el.clientHeight >= el.scrollHeight - 40) setScrolledEnd(true);
  };

  const handleAccept = async () => {
    if (!canSubmit) return;
    setSubmitting(true);
    setError(null);
    const { rec, error } = await acceptAgreement(fullName, ktp);
    setSubmitting(false);
    if (!rec) {
      // Surface a more specific message for known recoverable cases.
      let msg = t('Failed to record agreement. Please try again.', 'Gagal menyimpan persetujuan. Coba lagi.');
      if (error?.code === '23505') {
        // unique_violation — agent already accepted this doc version
        msg = t(
          'You have already accepted this agreement version. Reload the app to continue.',
          'Anda telah menyetujui versi perjanjian ini. Muat ulang aplikasi untuk melanjutkan.'
        );
      } else if (error?.code === '42P01') {
        // undefined_table — migration has not been applied yet
        msg = t(
          'Agreement storage is not configured yet. Please contact support.',
          'Penyimpanan perjanjian belum dikonfigurasi. Silakan hubungi dukungan.'
        );
      } else if (error?.code === '23503') {
        // foreign_key_violation — agent_id not in sp_users
        msg = t(
          'Your profile is not fully set up yet. Please log out and log back in.',
          'Profil kamu belum siap. Silakan keluar dan masuk kembali.'
        );
      } else if (error?.code === 'NO_USER') {
        msg = t(
          'Session expired. Please log out and log back in.',
          'Sesi berakhir. Silakan keluar dan masuk kembali.'
        );
      } else if (error?.message) {
        // Show the actual error message so the user (and support) can diagnose
        msg = `${t('Failed to save agreement:', 'Gagal menyimpan:')} ${error.message}`;
      }
      setError(msg);
      return;
    }
    setDone(rec);
  };

  const handleDownload = async () => {
    const rec = done;
    if (!rec) return;
    await generateAgreementPDF({
      agreementNo: rec.agreement_no,
      docVersion: rec.doc_version,
      fullName: rec.full_name,
      ktpNumber: rec.ktp_number,
      acceptedAt: rec.accepted_at,
      agentEmail: agent?.email,
      agentPhone: agent?.phone,
    });
  };

  // Success screen — agreement recorded
  if (done) {
    return (
      <div className="fixed inset-0 z-[4000] flex flex-col items-center justify-center px-6 text-center" style={{ background: '#f6faf7' }}>
        <div className="w-20 h-20 rounded-3xl flex items-center justify-center mb-6" style={{ background: 'linear-gradient(135deg,#10b981,#047857)', boxShadow: '0 18px 40px -14px rgba(16,185,129,0.7)' }}>
          <CheckCircle2 size={44} className="text-white" />
        </div>
        <h2 className="text-2xl font-black text-slate-900 mb-2">{t('Agreement Recorded', 'Perjanjian Tercatat')}</h2>
        <p className="text-sm text-slate-500 max-w-xs mb-1">
          {t('Your acceptance has been securely recorded.', 'Persetujuan Anda telah tersimpan dengan aman.')}
        </p>
        <p className="text-xs font-mono font-bold text-emerald-700 mb-8">{done.agreement_no}</p>
        <div className="w-full max-w-xs space-y-2.5">
          <button onClick={handleDownload}
            className="w-full flex items-center justify-center gap-2 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest text-emerald-700 bg-emerald-500/10 border border-emerald-500/25 active:scale-[0.98] transition-transform">
            <Download size={16} /> {t('Download PDF', 'Unduh PDF')}
          </button>
          <button onClick={() => onAccepted(done)}
            className="w-full flex items-center justify-center gap-2 py-3.5 rounded-2xl font-black text-sm uppercase tracking-widest text-white active:scale-[0.98] transition-transform"
            style={{ background: 'linear-gradient(135deg,#059669,#047857)', boxShadow: '0 14px 30px -12px rgba(5,150,105,0.6)' }}>
            {t('Enter App', 'Masuk Aplikasi')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[4000] flex flex-col" style={{ background: '#f6faf7' }}>
      {/* Header */}
      <div className="px-6 pt-8 pb-4 text-center flex-shrink-0" style={{ paddingTop: 'max(2rem, env(safe-area-inset-top))' }}>
        <div className="w-14 h-14 mx-auto rounded-2xl bg-white shadow-lg shadow-emerald-500/20 ring-1 ring-emerald-500/20 flex items-center justify-center mb-3">
          <ShieldCheck size={28} className="text-ds-green" />
        </div>
        <h1 className="text-lg font-black text-slate-900 tracking-tight">{AGREEMENT_META.title}</h1>
        <p className="text-[11px] font-bold uppercase tracking-widest text-ds-green mt-1">
          {AGREEMENT_META.version} · {t('Mandatory', 'Wajib Disetujui')}
        </p>
      </div>

      {/* Scrollable document */}
      <div ref={scrollRef} onScroll={onScroll}
        className="flex-1 overflow-y-auto no-scrollbar px-5 pb-4">
        <div className="max-w-xl mx-auto sp-glass rounded-2xl p-5 space-y-4">
          <div className="flex items-start gap-2 pb-3 border-b border-emerald-900/10">
            <FileText size={15} className="text-ds-green mt-0.5 flex-shrink-0" />
            <p className="text-[11px] text-slate-500 leading-relaxed">
              {t(
                `Between ${AGREEMENT_META.company.name} ("Company") and you as Mitra (Partner). Read fully before accepting.`,
                `Antara ${AGREEMENT_META.company.name} ("Perusahaan") dan Anda sebagai Mitra. Baca seluruhnya sebelum menyetujui.`
              )}
            </p>
          </div>
          {AGREEMENT_CLAUSES.map((cl, i) => (
            <div key={i} className="space-y-1.5">
              <h3 className="text-xs font-black text-emerald-800 tracking-tight">{cl.heading}</h3>
              {cl.body.map((p, j) => (
                <p key={j} className="text-[11.5px] text-slate-600 leading-relaxed">{p}</p>
              ))}
            </div>
          ))}
          <div className="pt-2 text-center">
            <span className="inline-block text-[10px] font-bold uppercase tracking-widest text-ds-green bg-emerald-500/10 px-3 py-1 rounded-full">
              — {t('End of Document', 'Akhir Dokumen')} —
            </span>
          </div>
        </div>
      </div>

      {/* Sticky acceptance form */}
      <div className="flex-shrink-0 px-5 pt-3 pb-5 sp-glass-strong border-t border-emerald-900/10" style={{ paddingBottom: 'max(1.25rem, env(safe-area-inset-bottom))' }}>
        <div className="max-w-xl mx-auto space-y-3">
          {!scrolledEnd && (
            <p className="text-center text-[11px] font-bold text-ds-amber flex items-center justify-center gap-1.5">
              <AlertCircle size={13} /> {t('Scroll to the end to continue', 'Gulir sampai akhir untuk melanjutkan')}
            </p>
          )}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
            <div>
              <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 mb-1 block">{t('Full Name (as per KTP)', 'Nama Lengkap (sesuai KTP)')}</label>
              <input value={fullName} onChange={e => setFullName(e.target.value)}
                placeholder={t('Full name', 'Nama lengkap')}
                className="w-full h-11 px-3.5 rounded-xl border border-emerald-900/10 bg-white/85 text-sm text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500/50" />
            </div>
            <div>
              <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 mb-1 block">{t('KTP Number (16 digits)', 'Nomor KTP (16 digit)')}</label>
              <input value={ktp} onChange={e => setKtp(e.target.value.replace(/\D/g, '').slice(0, 16))}
                inputMode="numeric" placeholder="3•••••••••••••••"
                className={`w-full h-11 px-3.5 rounded-xl border bg-white/85 text-sm font-mono tracking-wider text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-emerald-500/30 ${ktp.length > 0 && !ktpValid ? 'border-rose-400' : 'border-emerald-900/10 focus:border-emerald-500/50'}`} />
            </div>
          </div>

          <label className="flex items-start gap-2.5 cursor-pointer select-none">
            <input type="checkbox" checked={checked} onChange={e => setChecked(e.target.checked)}
              className="mt-0.5 w-4 h-4 rounded accent-emerald-600 flex-shrink-0" />
            <span className="text-[11px] text-slate-600 leading-snug">
              {t(
                'I have read, understood, and agree to be legally bound by this Partnership Agreement, including that data I provide is forwarded to the insurance company and that the insurance company holds final authority over acceptance and claims. My name and KTP number above serve as valid, voluntary electronic consent.',
                'Saya telah membaca, memahami, dan menyetujui untuk terikat secara hukum pada Perjanjian Kemitraan ini, termasuk bahwa data yang saya berikan akan diteruskan kepada perusahaan asuransi dan bahwa perusahaan asuransi memegang wewenang akhir atas akseptasi dan klaim. Nama dan Nomor KTP di atas merupakan persetujuan elektronik yang sah dan sukarela.'
              )}
            </span>
          </label>

          {error && (
            <p className="text-xs font-bold text-rose-600 flex items-center gap-1.5"><AlertCircle size={13} /> {error}</p>
          )}

          <button onClick={handleAccept} disabled={!canSubmit}
            className="w-full h-13 py-3.5 rounded-2xl font-black text-sm uppercase tracking-widest text-white flex items-center justify-center gap-2 transition-all active:scale-[0.98] disabled:opacity-40 disabled:cursor-not-allowed"
            style={{ background: 'linear-gradient(135deg,#059669,#047857)', boxShadow: canSubmit ? '0 14px 30px -12px rgba(5,150,105,0.6)' : 'none' }}>
            {submitting ? <Loader2 size={16} className="animate-spin" /> : <ShieldCheck size={16} />}
            {t('I AGREE', 'SAYA SETUJU')}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AgentAgreementGate;

import React, { useState, useEffect, useCallback } from 'react';
import {
  Search, Plus, X, Pencil, Trash2, RefreshCw,
  Phone, Mail, MapPin, FileText, ChevronRight, User, AlertCircle
} from 'lucide-react';
import { Language } from '../../types';
import {
  getAgentClients, addClient, updateClient, deleteClient, getAgentPolicies,
  type SpClient, type SpPolicy
} from '../../services/supabaseService';
import { formatIDR } from '../car-wizard/WizardUI';
import { AgentArtKeyframes, AgentHero, SpotClients, AgentEmpty } from './AgentArt';

interface Props {
  agentId: string;
  lang: Language;
  onSelectClient?: (client: SpClient) => void;
}

type FilterStatus = 'ALL' | 'PROSPECT' | 'ACTIVE' | 'INACTIVE';

const statusColors: Record<string, string> = {
  ACTIVE: 'bg-ds-green-tint text-ds-green',
  PROSPECT: 'bg-blue-50 text-ds-blue',
  INACTIVE: 'bg-ds-card2 text-ds-ink3',
};

const EMPTY_FORM = {
  name: '',
  phone: '',
  email: '',
  ktp: '',
  address: '',
  occupation: '',
  status: 'PROSPECT' as SpClient['status'],
  notes: '',
};

const AgentCRM: React.FC<Props> = ({ agentId, lang, onSelectClient }) => {
  const t = (en: string, id: string) => lang === Language.EN ? en : id;

  const [clients, setClients] = useState<SpClient[]>([]);
  const [policies, setPolicies] = useState<SpPolicy[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState<FilterStatus>('ALL');

  // Detail modal
  const [selectedClient, setSelectedClient] = useState<SpClient | null>(null);

  // Add/edit sheet
  const [showSheet, setShowSheet] = useState(false);
  const [editingClient, setEditingClient] = useState<SpClient | null>(null);
  const [form, setForm] = useState({ ...EMPTY_FORM });
  const [formError, setFormError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  // Delete confirm
  const [deleteTarget, setDeleteTarget] = useState<SpClient | null>(null);

  const loadData = useCallback(async () => {
    if (!agentId) return;
    setLoading(true);
    try {
      const [c, p] = await Promise.all([
        getAgentClients(agentId),
        getAgentPolicies(agentId),
      ]);
      setClients(c);
      setPolicies(p);
    } finally {
      setLoading(false);
    }
  }, [agentId]);

  useEffect(() => { loadData(); }, [loadData]);

  const filtered = clients.filter(c => {
    const matchFilter = filter === 'ALL' || c.status === filter;
    const q = search.toLowerCase();
    const matchSearch = !q || c.name.toLowerCase().includes(q) || (c.phone ?? '').includes(q) || (c.email ?? '').toLowerCase().includes(q);
    return matchFilter && matchSearch;
  });

  const clientPolicies = (clientId: string) => policies.filter(p => p.client_id === clientId);
  const clientPremiumTotal = (clientId: string) => clientPolicies(clientId).reduce((s, p) => s + p.premium, 0);

  const openAdd = () => {
    setEditingClient(null);
    setForm({ ...EMPTY_FORM });
    setFormError('');
    setShowSheet(true);
  };

  const openEdit = (client: SpClient, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingClient(client);
    setForm({
      name: client.name,
      phone: client.phone,
      email: client.email ?? '',
      ktp: client.ktp ?? '',
      address: client.address ?? '',
      occupation: client.occupation ?? '',
      status: client.status,
      notes: client.notes ?? '',
    });
    setFormError('');
    setShowSheet(true);
    setSelectedClient(null);
  };

  const handleSubmit = async () => {
    if (!form.name.trim()) { setFormError(t('Name is required.', 'Nama wajib diisi.')); return; }
    if (!form.phone.trim()) { setFormError(t('Phone is required.', 'No. HP wajib diisi.')); return; }
    setSubmitting(true);
    setFormError('');
    try {
      if (editingClient) {
        const updated = await updateClient(editingClient.id, form);
        if (updated) {
          setClients(prev => prev.map(c => c.id === editingClient.id ? updated : c));
        }
      } else {
        const created = await addClient({ ...form, agent_id: agentId });
        if (created) {
          setClients(prev => [created, ...prev]);
        }
      }
      setShowSheet(false);
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    const ok = await deleteClient(deleteTarget.id);
    if (ok) {
      setClients(prev => prev.filter(c => c.id !== deleteTarget.id));
      if (selectedClient?.id === deleteTarget.id) setSelectedClient(null);
    }
    setDeleteTarget(null);
  };

  const initials = (name: string) => name.split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2);

  const avatarColors = ['bg-blue-500', 'bg-emerald-500', 'bg-violet-500', 'bg-amber-500', 'bg-rose-500', 'bg-cyan-500'];
  const avatarColor = (name: string) => avatarColors[name.charCodeAt(0) % avatarColors.length];

  return (
    <div className="sp-agent-crm bg-ds-bg min-h-screen pb-28">

      {/* Hero banner */}
      <div className="px-5 pt-5">
        <AgentArtKeyframes />
        <AgentHero
          title={t('Client Book', 'Buku Klien')}
          subtitle={t('Your relationships, organized like a private banker.', 'Kelola relasi klien Anda serapi private banker.')}
          art={<SpotClients size={76} />}
        />
      </div>

      {/* Header */}
      <div className="bg-ds-card px-5 pt-4 pb-4 border-b border-ds-border mt-4">
        {/* Search */}
        <div className="relative mb-3">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-ds-ink3" />
          <input
            type="text"
            placeholder={t('Search clients…', 'Cari klien…')}
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full h-11 pl-10 pr-4 rounded-2xl sp-glass text-sm text-ds-ink placeholder:text-ds-ink3 focus:outline-none focus:ring-2 focus:ring-ds-green/30 focus:border-ds-green transition-all"
          />
        </div>

        {/* Filter Chips */}
        <div className="flex gap-2 overflow-x-auto pb-2 hide-scrollbar mb-2">
          {(['ALL', 'PROSPECT', 'ACTIVE', 'INACTIVE'] as FilterStatus[]).map(f => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`flex-shrink-0 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                filter === f
                  ? 'bg-ds-navy text-white shadow-ds-navy'
                  : 'bg-ds-card border border-ds-border text-ds-ink3'
              }`}
            >
              {f === 'ALL' ? t('All', 'Semua') : f}
            </button>
          ))}
        </div>

        {/* Count + Refresh */}
        <div className="flex items-center justify-between">
          <p className="text-sm text-ds-ink2">
            {filtered.length} {t('clients', 'klien')}
          </p>
          <button onClick={loadData} className="flex items-center gap-1.5 text-xs font-bold text-ds-ink3 hover:text-ds-green transition-colors">
            <RefreshCw size={12} className={loading ? 'animate-spin motion-reduce:animate-none' : ''} />
            {t('Refresh', 'Perbarui')}
          </button>
        </div>
      </div>

      {/* Client List */}
      <div className="px-4 py-3 space-y-2">
        {loading ? (
          Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="sp-glass rounded-2xl p-4 animate-pulse h-20" />
          ))
        ) : filtered.length === 0 ? (
          <div className="bg-ds-card2 rounded-2xl border border-ds-border mt-4">
            <AgentEmpty
              title={t('No clients found', 'Klien tidak ditemukan')}
              desc={t('Try adjusting your search or add a new client.', 'Coba ubah pencarian atau tambah klien baru.')}
            />
          </div>
        ) : (
          filtered.map(client => {
            const pols = clientPolicies(client.id);
            const total = clientPremiumTotal(client.id);
            return (
              <div
                key={client.id}
                onClick={() => { setSelectedClient(client); onSelectClient?.(client); }}
                className="sp-glass rounded-2xl p-4 flex items-center gap-3 active:sp-glass2 transition-colors cursor-pointer"
              >
                <div className="w-10 h-10 rounded-full bg-ds-green-tint flex items-center justify-center text-ds-green font-bold text-sm flex-shrink-0">
                  {initials(client.name)}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-semibold text-ds-ink truncate">{client.name}</p>
                    <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full flex-shrink-0 ${statusColors[client.status]}`}>
                      {client.status}
                    </span>
                  </div>
                  <p className="text-xs text-ds-ink3 mt-0.5">{client.phone}</p>
                  <div className="flex items-center gap-3 mt-1">
                    <span className="text-[10px] text-ds-ink3 font-bold">{pols.length} {t('pols', 'polis')}</span>
                    {total > 0 && <span className="text-[10px] text-ds-green font-bold">{formatIDR(total)}</span>}
                  </div>
                </div>
                <div className="flex items-center gap-1 flex-shrink-0">
                  <button
                    onClick={(e) => openEdit(client, e)}
                    className="w-8 h-8 rounded-xl bg-ds-card2 flex items-center justify-center hover:bg-ds-green-tint transition-colors"
                  >
                    <Pencil size={13} className="text-ds-ink3" />
                  </button>
                  <ChevronRight size={16} className="text-ds-ink3" />
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* FAB */}
      <button
        onClick={openAdd}
        className="fixed bottom-24 right-5 w-14 h-14 rounded-full bg-ds-green text-ds-on-green flex items-center justify-center shadow-ds-md active:brightness-90 transition-all z-30"
      >
        <Plus size={24} className="text-white" strokeWidth={3} />
      </button>

      {/* ─── Client Detail Modal ─── */}
      {selectedClient && (
        <div className="fixed inset-0 z-50 flex items-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setSelectedClient(null)} />
          <div className="relative w-full bg-ds-card rounded-t-[2rem] max-h-[85vh] overflow-y-auto shadow-ds-md">
            {/* Handle */}
            <div className="flex justify-center pt-3 pb-2">
              <div className="w-10 h-1 bg-ds-border rounded-full" />
            </div>

            <div className="px-5 pb-6 space-y-4">
              {/* Header */}
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className={`w-14 h-14 rounded-2xl ${avatarColor(selectedClient.name)} flex items-center justify-center`}>
                    <span className="text-white font-black text-lg">{initials(selectedClient.name)}</span>
                  </div>
                  <div>
                    <h2 className="font-black text-xl tracking-tight text-ds-ink">{selectedClient.name}</h2>
                    <span className={`text-[10px] font-black uppercase tracking-widest px-2.5 py-1 rounded-full ${statusColors[selectedClient.status]}`}>
                      {selectedClient.status}
                    </span>
                  </div>
                </div>
                <button onClick={() => setSelectedClient(null)} className="w-9 h-9 rounded-full bg-ds-card2 border border-ds-border flex items-center justify-center">
                  <X size={16} className="text-ds-ink2" />
                </button>
              </div>

              {/* Info */}
              <div className="bg-ds-card2 rounded-2xl border border-ds-border p-4 space-y-3">
                {selectedClient.phone && (
                  <div className="flex items-center gap-2 text-sm">
                    <Phone size={14} className="text-ds-ink3" />
                    <span className="font-medium text-ds-ink">{selectedClient.phone}</span>
                  </div>
                )}
                {selectedClient.email && (
                  <div className="flex items-center gap-2 text-sm">
                    <Mail size={14} className="text-ds-ink3" />
                    <span className="font-medium text-ds-ink">{selectedClient.email}</span>
                  </div>
                )}
                {selectedClient.address && (
                  <div className="flex items-center gap-2 text-sm">
                    <MapPin size={14} className="text-ds-ink3" />
                    <span className="font-medium text-ds-ink">{selectedClient.address}</span>
                  </div>
                )}
                {selectedClient.occupation && (
                  <div className="flex items-center gap-2 text-sm">
                    <User size={14} className="text-ds-ink3" />
                    <span className="font-medium text-ds-ink">{selectedClient.occupation}</span>
                  </div>
                )}
                {selectedClient.notes && (
                  <div className="pt-2 border-t border-ds-border">
                    <p className="text-[10px] font-bold text-ds-ink3 uppercase tracking-widest mb-2">{t('Notes', 'Catatan')}</p>
                    <p className="text-sm text-ds-ink">{selectedClient.notes}</p>
                  </div>
                )}
              </div>

              {/* Policies */}
              <div>
                <p className="text-[10px] font-bold text-ds-ink3 uppercase tracking-widest mb-2">
                  {t('Policies', 'Polis')} ({clientPolicies(selectedClient.id).length})
                </p>
                {clientPolicies(selectedClient.id).length === 0 ? (
                  <p className="text-ds-ink3 text-sm font-medium py-2">
                    {t('No policies yet.', 'Belum ada polis.')}
                  </p>
                ) : (
                  <div className="space-y-2">
                    {clientPolicies(selectedClient.id).map(pol => (
                      <div key={pol.id} className="flex items-center justify-between bg-ds-card2 border border-ds-border rounded-xl px-4 py-3">
                        <div>
                          <p className="font-bold text-sm text-ds-ink">{pol.policy_number ?? pol.type}</p>
                          <p className="text-xs text-ds-ink3">{pol.type} · {pol.status}</p>
                        </div>
                        <p className="font-black text-sm text-ds-green">{formatIDR(pol.premium)}</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* Actions */}
              <div className="grid grid-cols-2 gap-3 pt-2">
                <button
                  onClick={(e) => openEdit(selectedClient, e)}
                  className="py-3 rounded-2xl border border-ds-border bg-ds-card2 text-sm font-black uppercase tracking-widest text-ds-ink flex items-center justify-center gap-2 active:scale-95 transition-transform"
                >
                  <Pencil size={14} />
                  {t('Edit', 'Edit')}
                </button>
                <button
                  onClick={() => { setDeleteTarget(selectedClient); setSelectedClient(null); }}
                  className="py-3 rounded-2xl bg-rose-50 text-ds-red text-sm font-black uppercase tracking-widest flex items-center justify-center gap-2 active:scale-95 transition-transform"
                >
                  <Trash2 size={14} />
                  {t('Delete', 'Hapus')}
                </button>
              </div>

              <div className="flex items-center gap-2 p-3 bg-ds-green-tint rounded-2xl border border-ds-green/20">
                <FileText size={14} className="text-ds-green flex-shrink-0" />
                <p className="text-xs text-ds-green font-bold">
                  {t('Go to Quotes tab to create a new quote or policy for this client.', 'Buka tab Penawaran untuk membuat penawaran atau polis baru untuk klien ini.')}
                </p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ─── Add / Edit Sheet ─── */}
      {showSheet && (
        <div className="fixed inset-0 z-50 flex items-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSheet(false)} />
          <div className="relative w-full bg-ds-card rounded-t-[2rem] max-h-[90vh] overflow-y-auto shadow-ds-md">
            <div className="flex justify-center pt-3 pb-2">
              <div className="w-10 h-1 bg-ds-border rounded-full" />
            </div>
            <div className="px-5 pb-8 space-y-4">
              <div className="flex items-center justify-between">
                <h2 className="font-black text-xl tracking-tight text-ds-ink">
                  {editingClient ? t('Edit Client', 'Edit Klien') : t('Add Client', 'Tambah Klien')}
                </h2>
                <button onClick={() => setShowSheet(false)} className="w-9 h-9 rounded-full bg-ds-card2 border border-ds-border flex items-center justify-center">
                  <X size={16} className="text-ds-ink2" />
                </button>
              </div>

              {formError && (
                <div className="flex items-center gap-2 bg-rose-50 text-ds-red rounded-2xl px-4 py-3 text-sm font-bold">
                  <AlertCircle size={14} />
                  {formError}
                </div>
              )}

              <div className="space-y-3">
                {[
                  { key: 'name', label: t('Full Name *', 'Nama Lengkap *'), type: 'text', required: true },
                  { key: 'phone', label: t('Phone *', 'No. HP *'), type: 'tel', required: true },
                  { key: 'email', label: t('Email', 'Email'), type: 'email', required: false },
                  { key: 'ktp', label: t('KTP Number', 'No. KTP'), type: 'text', required: false },
                  { key: 'address', label: t('Address', 'Alamat'), type: 'text', required: false },
                  { key: 'occupation', label: t('Occupation', 'Pekerjaan'), type: 'text', required: false },
                ].map(field => (
                  <div key={field.key}>
                    <label className="text-[10px] font-bold text-ds-ink3 uppercase tracking-widest mb-1 block">
                      {field.label}
                    </label>
                    <input
                      type={field.type}
                      value={(form as any)[field.key]}
                      onChange={e => setForm(f => ({ ...f, [field.key]: e.target.value }))}
                      className="w-full bg-ds-card2 border border-ds-border rounded-2xl px-4 py-3 text-sm font-medium text-ds-ink focus:outline-none focus:ring-2 focus:ring-ds-green/40"
                    />
                  </div>
                ))}

                {/* Status */}
                <div>
                  <label className="text-[10px] font-bold text-ds-ink3 uppercase tracking-widest mb-1 block">
                    {t('Status', 'Status')}
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {(['PROSPECT', 'ACTIVE'] as SpClient['status'][]).map(s => (
                      <button
                        key={s}
                        onClick={() => setForm(f => ({ ...f, status: s }))}
                        className={`py-2.5 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${
                          form.status === s
                            ? s === 'ACTIVE'
                              ? 'bg-ds-green text-ds-on-green shadow-ds-sm'
                              : 'bg-ds-blue text-white shadow-ds-sm'
                            : 'bg-ds-card2 border border-ds-border text-ds-ink3'
                        }`}
                      >
                        {s}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Notes */}
                <div>
                  <label className="text-[10px] font-bold text-ds-ink3 uppercase tracking-widest mb-1 block">
                    {t('Notes', 'Catatan')}
                  </label>
                  <textarea
                    value={form.notes}
                    onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
                    rows={3}
                    className="w-full bg-ds-card2 border border-ds-border rounded-2xl px-4 py-3 text-sm font-medium text-ds-ink focus:outline-none focus:ring-2 focus:ring-ds-green/40 resize-none"
                  />
                </div>
              </div>

              <button
                onClick={handleSubmit}
                disabled={submitting}
                className="w-full py-4 bg-ds-navy text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-ds-navy active:scale-95 transition-transform disabled:opacity-50"
              >
                {submitting
                  ? t('Saving…', 'Menyimpan…')
                  : editingClient
                    ? t('Save Changes', 'Simpan Perubahan')
                    : t('Add Client', 'Tambah Klien')
                }
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ─── Delete Confirm ─── */}
      {deleteTarget && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setDeleteTarget(null)} />
          <div className="relative bg-ds-card rounded-[2rem] p-6 shadow-ds-md w-full max-w-sm border border-ds-border">
            <h3 className="font-black text-lg tracking-tight text-ds-ink mb-2">{t('Delete Client?', 'Hapus Klien?')}</h3>
            <p className="text-ds-ink2 text-sm mb-5">
              {t(`Are you sure you want to delete ${deleteTarget.name}? This cannot be undone.`, `Yakin ingin menghapus ${deleteTarget.name}? Tindakan ini tidak bisa dibatalkan.`)}
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setDeleteTarget(null)}
                className="flex-1 py-3 rounded-2xl border border-ds-border bg-ds-card2 text-ds-ink font-black text-xs uppercase tracking-widest"
              >
                {t('Cancel', 'Batal')}
              </button>
              <button
                onClick={handleDelete}
                className="flex-1 py-3 rounded-2xl bg-ds-red text-white font-black text-xs uppercase tracking-widest shadow-ds-sm"
              >
                {t('Delete', 'Hapus')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AgentCRM;

import React, { useState, useEffect } from 'react';
