          </div>
        </div>

        {/* Tier legend — dynamic, admin-configured */}
        {tiers.length > 0 && (
          <div className="sp-glass rounded-[2rem] p-5">
            <p className="text-[10px] font-bold text-ds-ink3 uppercase tracking-widest mb-3">
              {t('Tier Requirements', 'Syarat Tier')}
