const AgentPortal: React.FC<Props> = ({ agent, onLogout, lang }) => {
  const t = (en: string, id: string) => lang === Language.EN ? en : id;

  const [activeTab, setActiveTab] = useState('home');
  const [showOnboarding, setShowOnboarding] = useState(() => needsOnboarding('AGENT'));
  // Legal agreement gate — null = checking, false = must accept, true = signed
  const [agreementOk, setAgreementOk] = useState<boolean | null>(null);
  const [tabKey, setTabKey] = useState(0);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('sp_dark_mode') === 'true');
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [notificationPopup, setNotificationPopup] = useState<SpNotification | null>(null);
  const seenNotificationIds = useRef<Set<string>>(new Set());

  const [agentTier, setAgentTier] = useState<string | null>(null);
  const { tiers } = useTierDefinitions();
  const myTierDef = getTierByCode(tiers, agentTier);
  const [stats, setStats] = useState<AgentStats>({
    totalCommissionMonth: 0,
    totalCommissionAllTime: 0,
    clientsCount: 0,
    policiesCount: 0,
    pendingCommission: 0,
  });
  const [commissions, setCommissions] = useState<SpCommission[]>([]);
  const [clients, setClients] = useState<SpClient[]>([]);
  const [loading, setLoading] = useState(true);
  const [dataLoadError, setDataLoadError] = useState(false);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sp_dark_mode', String(darkMode));
  }, [darkMode]);

  // Check whether this agent has signed the current agreement version.
  // FIX v1.42.0: fail-closed — if the fetch errors, treat as NOT signed.
  // Previously this was fail-open (let agents bypass the legal gate on network blip).
  useEffect(() => {
    getMyAgreement()
      .then(rec => setAgreementOk(!!rec))
      .catch(() => setAgreementOk(false)); // fail-closed: require explicit acceptance
  }, []);

  const loadData = async () => {
    if (!agent?.id) return;
    setLoading(true);
    setDataLoadError(false);
    try {
      // Keep each dashboard panel independent: a notification outage should not
      // hide otherwise healthy commission, client, or policy data.
      const results = await Promise.allSettled([
        getAgentStats(agent.id, true),
        getAgentCommissions(agent.id, true),
        getAgentClients(agent.id, true),
        getNotifications(agent.id, true),
      ]);
      const [statsResult, commissionsResult, clientsResult, notificationsResult] = results;
      const hasError = results.some(result => result.status === 'rejected');

      if (statsResult.status === 'fulfilled') setStats(statsResult.value);
      else console.error('Error loading agent stats:', statsResult.reason);

      if (commissionsResult.status === 'fulfilled') setCommissions(commissionsResult.value);
      else console.error('Error loading agent commissions:', commissionsResult.reason);

      if (clientsResult.status === 'fulfilled') setClients(clientsResult.value);
      else console.error('Error loading agent clients:', clientsResult.reason);

      if (notificationsResult.status === 'fulfilled') {
        setUnreadCount(notificationsResult.value.filter(n => !n.read).length);
      } else {
        console.error('Error loading agent notifications:', notificationsResult.reason);
      }

      // Tier is optional metadata; a failure here should not break the dashboard.
      try {
        const { data: tierData, error: tierError } = await supabase
          .from('sp_users')
          .select('tier')
          .eq('id', agent.id)
          .single();
        if (tierError) {
          console.error('Error loading optional agent tier metadata:', tierError);
        } else if (tierData?.tier) {
          setAgentTier(tierData.tier);
        }
      } catch (tierError) {
        console.error('Error loading optional agent tier metadata:', tierError);
      }
      setDataLoadError(hasError);
    } catch (err) {
      console.error('Error loading agent data:', err);
      setDataLoadError(true);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadData(); }, [agent?.id]);

  // Account-scoped notification polling. Existing unread items update the badge
  // on login; only newly-arrived items trigger a popup while this account is active.
  useEffect(() => {
    if (!agent?.id) return;
    let cancelled = false;
    let initialized = false;

    const refreshNotifications = async () => {
      try {
        const items = await getNotifications(agent.id, true);
        if (cancelled) return;
        const currentIds = new Set(items.map(item => item.id));
        if (!initialized) {
          seenNotificationIds.current = currentIds;
          const firstUnread = items.find(item => !item.read);
          if (firstUnread) setNotificationPopup(firstUnread);
          initialized = true;
        } else {
          const fresh = items.find(item => !seenNotificationIds.current.has(item.id));
          if (fresh) setNotificationPopup(fresh);
          seenNotificationIds.current = currentIds;
        }
        setUnreadCount(items.filter(item => !item.read).length);
      } catch (error) {
        // Notifications are non-critical; never interrupt the agent workflow.
        console.error('Unable to refresh agent notifications:', error);
      }
    };

    seenNotificationIds.current = new Set();
    void refreshNotifications();
    const interval = window.setInterval(() => { void refreshNotifications(); }, 30000);
    return () => {
      cancelled = true;
      window.clearInterval(interval);
      seenNotificationIds.current = new Set();
    };
  }, [agent?.id]);

  const handleTabChange = (tab: string) => {
    setTabKey(k => k + 1);
    setActiveTab(tab);
    scrollPortalToTop();
  };

  const renderTab = () => {
    switch (activeTab) {
      case 'home':
        return (
          <AgentHome
            agent={agent}
            agentId={agent?.id ?? ''}
            stats={stats}
            recentCommissions={commissions.slice(0, 5)}
            onNavigate={handleTabChange}
            lang={lang}
            agentTier={agentTier}
          />
        );
      case 'policy':
        return (
          <PolicyAndQuotes
            agentId={agent?.id ?? ''}
            agent={agent}
            clients={clients}
            lang={lang}
            onNavigate={handleTabChange}
          />
        );
      case 'clients':
        return <AgentCRM agentId={agent?.id ?? ''} lang={lang} />;
      case 'quotes':
        return (
          <AgentQuoteBuilder
            agentId={agent?.id ?? ''}
            clients={clients}
            lang={lang}
            onBack={() => handleTabChange('home')}
            agent={agent}
            quoteOnly
          />
        );
      case 'claims':
        return <AgentClaims agentId={agent?.id ?? ''} lang={lang} />;
      case 'commission':
        return <AgentCommission agentId={agent?.id ?? ''} lang={lang} onNavigate={handleTabChange} />;
      case 'wallet':
        return <AgentWalletView />;
      case 'leaderboard':
        return (
          <AgentLeaderboard
            agentId={agent?.id ?? ''}
            agentName={agent?.name ?? ''}
            lang={lang}
            agentTier={agentTier}
          />
        );
      case 'renewals':
        return (
          <RenewalManager
            agentId={agent?.id ?? ''}
            lang={lang}
            agent={agent}
          />
        );
      case 'network':
        return (
          <AgentNetwork
            agentId={agent?.id ?? ''}
            lang={lang}
            agent={agent}
          />
        );
      case 'endorsements':
        return <AgentEndorsements agentId={agent?.id ?? ''} lang={lang} />;
      case 'profile':
        return (
          <AgentProfile
            agent={agent}
            agentId={agent?.id ?? ''}
            lang={lang}
            onLogout={onLogout}
            stats={stats}
            agentTier={agentTier}
          />
        );
      default:
        return null;
    }
  };

  // Legal agreement gate blocks all app access until signed
  if (agreementOk === false) {
    return <AgentAgreementGate agent={agent} lang={lang} onAccepted={() => setAgreementOk(true)} />;
  }

  return (
    <div className="sp-modern-app sp-agent-premium min-h-screen bg-ds-bg dark:bg-ds-dk-bg text-ds-ink dark:text-ds-dk-ink transition-colors duration-300 font-sora">
      <div aria-hidden className="sp-ambient" />
      {showOnboarding && agreementOk && (
        <OnboardingFlow role="AGENT" lang={lang === Language.EN ? 'EN' : 'ID'} onComplete={() => setShowOnboarding(false)} />
      )}
      <style>{`
        @keyframes spFadeIn {
          from { opacity: 0; transform: translateY(6px); }
          to   { opacity: 1; transform: translateY(0); }
        }
        @media (prefers-reduced-motion: reduce) {
          [data-sp-anim] { animation: none !important; }
        }
      `}</style>

      <PortalHeader
        portalLabel={t('Agent', 'Mitra')}
        userName={agent?.name ?? 'Agent'}
        userCode={agent?.agent_code ?? 'SP-AGT'}
        userMeta={myTierDef && !myTierDef.is_default ? (
          <div className="text-[8px] font-black uppercase tracking-widest" style={{ color: myTierDef.color }}>
            {myTierDef.emoji} {myTierDef.name}
          </div>
        ) : undefined}
        unreadCount={unreadCount}
        onBellClick={() => { setNotificationPopup(null); setShowNotifications(true); }}
        darkMode={darkMode}
        onToggleDark={() => setDarkMode(!darkMode)}
        onAvatarClick={() => handleTabChange('profile')}
        BellIcon={IcBell}
        labels={{
          notifications: t('Notifications', 'Notifikasi'),
          theme: t('Toggle theme', 'Ganti tema'),
          profile: t('Profile', 'Profil'),
        }}
      />

      {/* Main Content */}
      <main className="relative z-10 pb-32 min-h-screen" style={{ paddingTop: "calc(4rem + env(safe-area-inset-top, 0px))" }}>
        {loading && activeTab === 'home' ? (
          <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
            <div className="w-12 h-12 rounded-full border-4 border-ds-green/20 border-t-ds-green animate-spin motion-reduce:animate-none" />
            <p className="text-ds-ink3 text-sm font-bold">{t('Loading your dashboard…', 'Memuat dashboard…')}</p>
          </div>
        ) : (
          <>
            {dataLoadError && (
              <div role="alert" aria-live="polite" className="mx-5 mb-4 rounded-2xl border border-ds-amber/30 bg-ds-amber/10 p-4">
                <p className="text-sm font-bold text-ds-ink">{t('Some dashboard data could not be refreshed.', 'Sebagian data dashboard belum berhasil dimuat.')}</p>
                <p className="mt-1 text-xs text-ds-ink3">{t('You can keep using available sections or retry the refresh.', 'Kamu tetap bisa menggunakan bagian yang tersedia atau mencoba memuat ulang.')}</p>
                <button type="button" onClick={() => void loadData()} disabled={loading} className="mt-3 min-h-10 rounded-xl bg-ds-green px-4 py-2 text-xs font-black text-ds-on-green disabled:opacity-50">
                  {t('Retry refresh', 'Coba muat ulang')}
                </button>
              </div>
            )}
            <div key={tabKey} data-sp-anim className="sp-page-enter">
              {renderTab()}
            </div>
          </>
        )}
      </main>

      <PortalTabBar tabs={TABS} activeId={activeTab} onSelect={handleTabChange} modernIcons />

      {/* Notification drawer */}
      {showNotifications && (
        <AgentNotifications
          agentId={agent?.id ?? ''}
          lang={lang}
          onClose={() => {
            setShowNotifications(false);
            void getNotifications(agent?.id ?? '', true)
              .then(items => setUnreadCount(items.filter(item => !item.read).length))
              .catch(() => {});
          }}
          onNavigate={handleTabChange}
        />
      )}

      {notificationPopup && !showNotifications && !showOnboarding && (
        <div className="fixed right-4 z-[60] w-[min(22rem,calc(100vw-2rem))] animate-in fade-in slide-in-from-bottom-2"
          style={{ bottom: 'calc(env(safe-area-inset-bottom, 0px) + 6.5rem)' }}
          role="status" aria-live="polite">
          <div className="rounded-2xl border border-ds-border bg-ds-card p-4 shadow-2xl">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 shrink-0 rounded-xl bg-ds-green-tint flex items-center justify-center text-ds-green">
                <IcBell size={18} />
              </div>
              <button type="button" className="min-w-0 flex-1 text-left"
                onClick={() => { setNotificationPopup(null); setShowNotifications(true); }}>
                <span className="block text-[10px] font-black uppercase tracking-widest text-ds-green">{t('New notification', 'Notifikasi baru')}</span>
                <span className="mt-1 block text-sm font-bold text-ds-ink">{notificationPopup.title}</span>
                <span className="mt-0.5 block text-xs leading-relaxed text-ds-ink2">{notificationPopup.body}</span>
                <span className="mt-2 block text-xs font-bold text-ds-green">{t('View notifications', 'Lihat notifikasi')}</span>
              </button>
              <button type="button" aria-label={t('Dismiss notification popup', 'Tutup popup notifikasi')}
                onClick={() => setNotificationPopup(null)}
                className="min-h-8 min-w-8 rounded-full text-ds-ink3 hover:bg-ds-card2 flex items-center justify-center">
                <span aria-hidden="true">×</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Pathy assistant */}
      <PathyChat lang={lang} currentUser={{ name: agent.name, id: agent.id, role: agent.role }} />
    </div>
  );
};

export default AgentPortal;

import React, { useState, useEffect, useRef } from 'react';
import {
  User, Mail, Phone, MapPin, ShieldCheck, BadgeCheck,
  Edit2, Save, X, LogOut, Copy, CheckCircle, 
  Trophy, Loader2, Network, RefreshCw, FileEdit, Coins, Wallet,
  AlertCircle, Camera, Building2, ChevronRight, FileCheck2, Download,
} from 'lucide-react';
import { Language } from '../../types';
import { APP_VERSION } from '../../src/version';
import {
  getAgentProfile, updateAgentProfile, getAgentStats,
  uploadAgentAvatar, uploadAgentKtp,
  type SpUser, type AgentStats,
} from '../../services/supabaseService';
import { formatIDR } from '../car-wizard/WizardUI';
import { SecureDocLink } from '../shared/SecureDoc';
import AgentHandlerCard from './AgentHandlerCard';
import { getMyAgreement, type SpAgentAgreement } from '../../services/agreements';
import { generateAgreementPDF } from '../../services/agreementPdf';
import { useTierDefinitions, getTierByCode } from '../../hooks/useTierDefinitions';

interface Props {
  agent: any;
  agentId: string;
  lang: Language;
  onLogout: () => void;
  onNavigate?: (tab: string) => void;
  stats?: AgentStats | null;
  agentTier?: string | null;
}

const inputCls =
  'w-full rounded-xl border border-ds-border bg-ds-card2 px-4 py-3 text-ds-ink text-sm focus:outline-none focus:ring-2 focus:ring-ds-green transition';

const AgentProfile: React.FC<Props> = ({ agent, agentId, lang, onLogout, onNavigate, stats: statsProp, agentTier }) => {
  const t = (en: string, id: string) => lang === Language.EN ? en : id;

  const [profile, setProfile] = useState<SpUser | null>(null);
  const [stats, setStats] = useState<AgentStats | null>(null);
  const [agreement, setAgreement] = useState<SpAgentAgreement | null>(null);
  const [agreementLoading, setAgreementLoading] = useState(true);
  const [agreementDownloading, setAgreementDownloading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [copied, setCopied] = useState(false);
  const [avatarUploading, setAvatarUploading] = useState(false);
  const [ktpUploading, setKtpUploading] = useState(false);
  const avatarInputRef = useRef<HTMLInputElement>(null);
  const ktpInputRef = useRef<HTMLInputElement>(null);
  const { tiers } = useTierDefinitions();

  const [form, setForm] = useState({ name: '', phone: '', address: '' });

  interface BankAccount { bank_code: string; account_number: string; account_holder_name: string; }
  const BANK_STORAGE_KEY = 'SUREPATH_SAVED_BANK';
  // FIX v1.42.0: use sessionStorage instead of localStorage for bank PII.
  const BANK_STORAGE: Storage | null = typeof sessionStorage !== 'undefined' ? sessionStorage : null;
  const [savedAccount, setSavedAccount] = useState<BankAccount | null>(() => {
    try { return JSON.parse(BANK_STORAGE?.getItem(BANK_STORAGE_KEY) ?? 'null'); } catch { return null; }
  });
  const [showBankForm, setShowBankForm] = useState(false);
  const [bankForm, setBankForm] = useState({ bank_code: '', account_number: '', account_holder_name: '' });

  const INDONESIAN_BANKS = ['BCA', 'BRI', 'BNI', 'Mandiri', 'CIMB Niaga', 'BSI', 'Permata'];

  const saveBankAccount = () => {
    if (!bankForm.bank_code || !bankForm.account_number || !bankForm.account_holder_name) return;
    BANK_STORAGE?.setItem(BANK_STORAGE_KEY, JSON.stringify(bankForm));
    setSavedAccount(bankForm);
    setShowBankForm(false);
    setBankForm({ bank_code: '', account_number: '', account_holder_name: '' });
  };

  const deleteBankAccount = () => {
    BANK_STORAGE?.removeItem(BANK_STORAGE_KEY);
    setSavedAccount(null);
  };

  useEffect(() => {
    if (!agentId) return;
    setAgreementLoading(true);
    Promise.all([getAgentProfile(agentId), getAgentStats(agentId), getMyAgreement()]).then(
      ([prof, st, signedAgreement]) => {
        setAgreement(signedAgreement);
        if (prof) {
          setProfile(prof);
          setForm({ name: prof.name, phone: prof.phone, address: prof.address ?? '' });
        }
        setStats(statsProp ?? st);
        setLoading(false);
        setAgreementLoading(false);
      },
    ).catch(() => {
      setLoading(false);
      setAgreementLoading(false);
    });
  }, [agentId, statsProp]);

  const handleSave = async () => {
    if (!agentId) return;
    setSaving(true);
    const ok = await updateAgentProfile(agentId, form);
    if (ok) {
      setProfile(prev => prev ? { ...prev, ...form } : prev);
      setEditing(false);
    }
    setSaving(false);
  };

  const handleCancel = () => {
    if (profile) setForm({ name: profile.name, phone: profile.phone, address: profile.address ?? '' });
    setEditing(false);
  };

  const copyCode = () => {
    navigator.clipboard.writeText(profile?.agent_code ?? '').catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleAvatarChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setAvatarUploading(true);
    const url = await new Promise<string>(res => {
      const reader = new FileReader();
      reader.onload = ev => {
        const img = new Image();
        img.onload = () => {
          const s = Math.min(1, 400 / Math.max(img.width, img.height));
          const c = document.createElement('canvas');
          c.width = Math.round(img.width * s);
          c.height = Math.round(img.height * s);
          c.getContext('2d')!.drawImage(img, 0, 0, c.width, c.height);
          res(c.toDataURL('image/jpeg', 0.82));
        };
        img.src = ev.target!.result as string;
      };
      reader.readAsDataURL(file);
    });
    const publicUrl = await uploadAgentAvatar(agentId, url);
    if (publicUrl) {
      setProfile(p => p ? { ...p, profile_photo_url: publicUrl } as any : p);
    }
    setAvatarUploading(false);
  };

  const handleKtpChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setKtpUploading(true);
    const url = await uploadAgentKtp(agentId, file);
    if (url) setProfile(p => p ? { ...p, ktp_document_url: url } as any : p);
    setKtpUploading(false);
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
        <Loader2 className="w-10 h-10 text-ds-green animate-spin motion-reduce:animate-none" />
        <p className="text-ds-ink3 text-sm">{t('Loading profile…', 'Memuat profil…')}</p>
      </div>
    );
  }

  const initials = (profile?.name ?? agent?.name ?? 'A')
    .split(' ')
    .slice(0, 2)
    .map((w: string) => w[0])
    .join('')
    .toUpperCase();

  const tierCode = agentTier ?? (profile as any)?.tier ?? (profile as any)?.agent_tier ?? agent?.tier ?? agent?.agent_tier;
  const tierDef = getTierByCode(tiers, tierCode);

  return (
    <div className="bg-ds-bg min-h-screen pb-28 font-sora">

      {/* Avatar + Name hero — bank-style gradient banner */}
      <div className="relative overflow-hidden px-5 pt-12 pb-7 text-center text-white"
        style={{ background: 'linear-gradient(150deg, #0B1120 0%, #0E3B2E 60%, #0B5E3B 100%)' }}>
        <div aria-hidden className="absolute -top-16 -right-12 w-56 h-56 rounded-full pointer-events-none" style={{ background: 'radial-gradient(circle, rgba(0,193,106,0.25), transparent 70%)' }} />
        <svg aria-hidden className="absolute left-0 bottom-0 h-3/4 opacity-[0.10] pointer-events-none" viewBox="0 0 200 140" fill="none">
          <circle cx="10" cy="130" r="80" stroke="#fff" strokeWidth="1.2" />
          <circle cx="10" cy="130" r="52" stroke="#fff" strokeWidth="1.2" />
        </svg>
        <div className="relative z-10">
        <div className="relative w-20 h-20 mx-auto mb-3">
          <button
            onClick={() => avatarInputRef.current?.click()}
            className="w-20 h-20 rounded-full flex items-center justify-center text-white font-bold text-2xl mx-auto overflow-hidden relative ring-4 ring-white/15"
            style={{ background: 'linear-gradient(135deg, #00C16A, #047857)' }}
          >
            {(profile as any)?.profile_photo_url
              ? <img loading="lazy" src={(profile as any).profile_photo_url} alt="Avatar" className="w-full h-full object-cover" />
              : <span>{initials}</span>
            }
            {avatarUploading && (
              <div className="absolute inset-0 bg-black/50 flex items-center justify-center">
                <div className="w-5 h-5 rounded-full border-2 border-white/20 border-t-white animate-spin motion-reduce:animate-none" />
              </div>
            )}
            <div className="absolute bottom-0.5 right-0.5 w-6 h-6 rounded-full bg-white flex items-center justify-center shadow">
              <Camera size={11} className="text-sp-emerald" />
            </div>
          </button>
          <input ref={avatarInputRef} type="file" accept="image/*" className="hidden" onChange={handleAvatarChange} />
        </div>

        <h2 className="text-lg font-black text-white">{profile?.name ?? agent?.name}</h2>

        <div className="flex items-center justify-center gap-2 mt-1.5">
          <span className="inline-flex px-3 py-1 rounded-full bg-white/10 border border-white/15 text-white/85 text-xs font-bold tracking-wider font-mono">
            {profile?.agent_code ?? agent?.agent_code}
          </span>
          <button onClick={copyCode} className="text-white/60 hover:text-white transition">
            {copied
              ? <CheckCircle className="w-3.5 h-3.5 text-ds-green" />
              : <Copy className="w-3.5 h-3.5" />}
          </button>
        </div>

        <div className="flex items-center justify-center gap-2 mt-2.5 flex-wrap">
          {profile?.verified && (
            <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full bg-white/10 border border-white/15 text-sky-300 text-xs font-bold">
              <BadgeCheck className="w-3.5 h-3.5" />
              {t('Verified Partner', 'Mitra Terverifikasi')}
            </span>
          )}
          {tierDef && !tierDef.is_default && (
            <span
              className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-black border border-white/15 bg-white/10"
              style={{ color: tierDef.color }}
            >
              {tierDef.emoji} {tierDef.name}
            </span>
          )}
        </div>
        </div>
      </div>

      {/* Stats strip */}
      {stats && (
        <div className="flex bg-ds-card border-b border-ds-border">
          {[
            { value: stats.policiesCount, label: t('Policies', 'Polis') },
            { value: formatIDR(stats.totalCommissionAllTime), label: t('Total Earned', 'Total Komisi') },
            { value: stats.clientsCount, label: t('Clients', 'Klien') },
          ].map((item, i) => (
            <div key={i} className="flex-1 text-center px-2 py-4 border-r last:border-r-0 border-ds-border">
              <p className="text-sm font-black text-ds-ink font-mono">{item.value}</p>
              <p className="text-[10px] text-ds-ink3 font-bold mt-0.5 uppercase tracking-widest">{item.label}</p>
            </div>
          ))}
        </div>
      )}

      {tierDef && (
        <section className="mx-5 mt-4 rounded-2xl border border-ds-border bg-ds-card p-4" aria-label={t('Agent tier details', 'Detail tier agen')}>
          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl text-xl" style={{ color: tierDef.color || '#64748b', background: `${tierDef.color || '#64748b'}18` }}>
              {tierDef.emoji || '✦'}
            </div>
            <div className="min-w-0 flex-1">
              <p className="text-[10px] font-bold uppercase tracking-widest text-ds-ink3">{t('Your partner tier', 'Tier mitra Anda')}</p>
              <p className="text-base font-black text-ds-ink">{tierDef.name}</p>
            </div>
            <span className="rounded-full px-2.5 py-1 text-[10px] font-bold" style={{ color: tierDef.color || '#64748b', background: `${tierDef.color || '#64748b'}18` }}>
              {tierDef.is_default ? t('Starting tier', 'Tier awal') : t('Active tier', 'Tier aktif')}
            </span>
          </div>
          <div className="mt-3 grid grid-cols-3 gap-2">
            <div className="rounded-xl bg-ds-card2 p-2.5">
              <p className="text-[9px] font-bold uppercase tracking-wide text-ds-ink3">{t('Coin bonus', 'Bonus koin')}</p>
              <p className="mt-1 text-sm font-black text-ds-ink">{Math.round((tierDef.coin_bonus_rate ?? 0) * 100)}%</p>
            </div>
            <div className="rounded-xl bg-ds-card2 p-2.5">
              <p className="text-[9px] font-bold uppercase tracking-wide text-ds-ink3">L1</p>
              <p className="mt-1 text-sm font-black text-ds-ink">{Math.round((tierDef.l1_override_rate ?? 0) * 100)}%</p>
            </div>
            <div className="rounded-xl bg-ds-card2 p-2.5">
              <p className="text-[9px] font-bold uppercase tracking-wide text-ds-ink3">L2</p>
              <p className="mt-1 text-sm font-black text-ds-ink">{Math.round((tierDef.l2_override_rate ?? 0) * 100)}%</p>
            </div>
          </div>
        </section>
      )}

      {/* Marketing pendamping — read-only; penugasan hanya dari CMS. */}
      <AgentHandlerCard />

      {/* Referral Link */}
      <div className="mx-5 mt-4 sp-glass rounded-2xl p-4">
        <p className="text-[10px] font-bold text-ds-ink3 uppercase tracking-widest mb-2">Link Rekrutmen Mitra</p>
        <div className="flex items-center gap-2 bg-ds-card2 rounded-xl p-3">
          <p className="text-xs font-mono text-ds-ink2 flex-1 truncate">
            https://myinsurepath.com?ref={profile?.agent_code}
          </p>
          <button
            onClick={() => { navigator.clipboard.writeText(`https://myinsurepath.com?ref=${profile?.agent_code}`); }}
            className="text-ds-green hover:text-ds-green-dk transition"
          >
            <Copy className="w-4 h-4" />
          </button>
        </div>
        <p className="text-[9px] text-ds-ink3 mt-2">Bagikan link ini untuk merekrut agen baru di bawah kamu.</p>
      </div>

      {/* Partnership agreement — fetched from the signed agreement record for the authenticated agent. */}
      <section className="mx-5 mt-4 rounded-2xl sp-glass overflow-hidden" aria-labelledby="agent-agreement-heading">
        <div className="px-5 py-4 flex items-center gap-3 border-b border-ds-border">
          <div className="w-10 h-10 rounded-xl bg-ds-green-tint flex items-center justify-center">
            <FileCheck2 className="w-5 h-5 text-ds-green" />
          </div>
          <div className="flex-1 min-w-0">
            <h3 id="agent-agreement-heading" className="text-sm font-black text-ds-ink">{t('Partnership Agreement', 'Perjanjian Mitra')}</h3>
            <p className="text-xs text-ds-ink3 mt-0.5">{t('Your signed agreement record', 'Catatan perjanjian yang telah disetujui')}</p>
          </div>
          {agreement && <span className="text-[10px] font-black px-2.5 py-1 rounded-full bg-ds-green-tint text-ds-green">{t('RECORDED', 'TERCATAT')}</span>}
        </div>
        <div className="p-5">
          {agreementLoading ? (
            <div className="flex items-center gap-2 text-sm text-ds-ink3"><Loader2 className="w-4 h-4 animate-spin" />{t('Loading agreement…', 'Memuat agreement…')}</div>
          ) : agreement ? (
            <>
