                <Bike
                  className={`w-12 h-12 ${isActive ? 'text-ds-green' : 'text-slate-400'}`}
                />
              )}
              <span
                className={`font-black text-sm uppercase tracking-wide ${
                  isActive ? 'text-ds-green' : 'text-slate-600 dark:text-slate-300'
