            </div>
            {/* Year */}
            <div>
              <Label>Tahun *</Label>
              <select
                value={vehicleDetails.year}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                  handleVehicleDetailChange('year', parseInt(e.target.value, 10))
