            {/* Engine */}
            <div>
              <Label>Nomor Mesin *</Label>
              <input
                type="text"
                value={vehicleDetails.engine}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                  handleVehicleDetailChange('engine', e.target.value.toUpperCase())
