      {/* Recent submissions */}
      {recent.length > 0 && (
        <div>
          <div className="flex items-center justify-between mb-3">
            <h3 className="font-black text-sm uppercase tracking-wide text-slate-700 dark:text-slate-300">
              {t('Recent Submissions', 'Pengajuan Terbaru')}
