                  <span className={`text-2xs font-black uppercase tracking-wider px-2 py-1 rounded-full ${STATUS_BADGE[sub.status] ?? ''}`}>
                    {sub.status}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

